import { useEffect, useMemo, useState } from "react";
import { invoke } from "@tauri-apps/api/core";
import { getCurrentWebview } from "@tauri-apps/api/webview";
import { open, save } from "@tauri-apps/plugin-dialog";
import { AlertTriangle, Archive, BarChart3, FileSearch, Gauge, History, Mail, Paperclip, Search, Settings, ShieldCheck, Trash2, Download, RefreshCw, Shield, Link2, Code2, Route, Fingerprint, FileWarning, Languages, Database, Globe2, Bug, Radar, Server, Eye, Copy, RotateCcw, FilePlus2 } from "lucide-react";
import type { AnalysisResult, AuditEntry, CaseMetadata, DashboardStats, EngineStatus, HistoryItem, IOC, UiBootstrap, YaraStatus } from "./types";
import mailScopeIcon from "./assets/mailscope-icon.png";
import vtLogo from "./assets/providers/virustotal.png";
import urlhausLogo from "./assets/providers/urlhaus.png";
import threatfoxLogo from "./assets/tools/threatfox.svg";
import malwarebazaarLogo from "./assets/providers/malwarebazaar.png";
import otxLogo from "./assets/providers/otx.png";
import abuseipdbLogo from "./assets/providers/abuseipdb.png";
import urlscanLogo from "./assets/providers/urlscan.png";
import circlLogo from "./assets/providers/circl.png";


type Page = "Dashboard" | "New Analysis" | "History" | "IOC Explorer" | "Threat Intelligence" | "Reports" | "Settings";
const navItems: [Page, string, any][] = [["Dashboard","Dashboard",Gauge],["New Analysis","Analyze",FileSearch],["History","Cases",History],["IOC Explorer","Indicators",Search],["Threat Intelligence","Intelligence",Globe2],["Reports","Reports",Archive],["Settings","Settings",Settings]];
const pageTitles:Record<Page,string>={Dashboard:"Dashboard","New Analysis":"Analyze","History":"Cases","IOC Explorer":"Indicators","Threat Intelligence":"Intelligence",Reports:"Reports",Settings:"Settings"};
const fmt = (n:number) => n<1024?`${n} B`:n<1048576?`${(n/1024).toFixed(1)} KB`:`${(n/1048576).toFixed(1)} MB`;
const dateFmt=(v:string)=>{try{return new Date(v).toLocaleString()}catch{return v}};
const severityRank:Record<string,number>={critical:5,high:4,medium:3,low:2,info:1};
const reportStem=(fileName:string)=>fileName.replace(/^.*[\\/]/,"").replace(/\.[^.]+$/,"")||"report";

let historyCache:HistoryItem[]|null=null;
let dashboardCache:DashboardStats|null=null;
let settingsCache:OnlineSettings|null=null;
const analysisCache=new Map<string,AnalysisResult>();
let bootstrapRequest:Promise<UiBootstrap<OnlineSettings>>|null=null;

function cacheAnalysis(result:AnalysisResult|null){
  if(!result)return;
  analysisCache.set(result.analysis_id,{...result,duplicate:false,duplicate_message:undefined});
}
function invalidateCaseCaches(){historyCache=null;dashboardCache=null}
async function loadUiBootstrap(){
  if(!bootstrapRequest){
    bootstrapRequest=invoke<UiBootstrap<OnlineSettings>>("ui_bootstrap").then(data=>{
      historyCache=data.history;dashboardCache=data.stats;settingsCache={...defaultOnline,...data.settings};cacheAnalysis(data.latest_analysis);return data;
    }).catch(error=>{bootstrapRequest=null;throw error});
  }
  return bootstrapRequest;
}
async function waitForBootstrap(){if(bootstrapRequest){try{await bootstrapRequest}catch{/* individual request reports its own error */}}}
async function loadHistory(force=false){await waitForBootstrap();if(historyCache&&!force)return historyCache;historyCache=await invoke<HistoryItem[]>("list_history");return historyCache}
async function loadDashboard(force=false){await waitForBootstrap();if(dashboardCache&&!force)return dashboardCache;dashboardCache=await invoke<DashboardStats>("dashboard_stats");return dashboardCache}
async function loadAnalysis(id:string,force=false){await waitForBootstrap();if(!force&&analysisCache.has(id))return analysisCache.get(id)!;const result=await invoke<AnalysisResult>("get_analysis",{analysisId:id});cacheAnalysis(result);return result}
async function loadOnlineSettings(force=false){await waitForBootstrap();if(settingsCache&&!force)return settingsCache;settingsCache={...defaultOnline,...await invoke<OnlineSettings>("get_settings")};return settingsCache}

export default function App(){
  const [page,setPage]=useState<Page>("New Analysis");
  const [engine,setEngine]=useState<EngineStatus|null>(null);
  const [error,setError]=useState("");
  const [analysis,setAnalysis]=useState<AnalysisResult|null>(null);
  const [selectedPath,setSelectedPath]=useState("");
  const [loading,setLoading]=useState(false);
  const [refreshKey,setRefreshKey]=useState(0);
  const [engineChecking,setEngineChecking]=useState(true);
  const checkEngine=async()=>{setEngineChecking(true);setError("");try{setEngine(await invoke<EngineStatus>("engine_status"))}catch(e){setEngine(null);setError(String(e))}finally{setEngineChecking(false)}};
  useEffect(()=>{let active=true;setEngineChecking(true);loadUiBootstrap().then(data=>{if(!active)return;setEngine(data.engine);setAnalysis(data.latest_analysis)}).catch(e=>{if(active){setEngine(null);setError(String(e))}}).finally(()=>{if(active)setEngineChecking(false)});return()=>{active=false}},[]);
  useEffect(()=>{cacheAnalysis(analysis)},[analysis]);
  const dataChanged=()=>{invalidateCaseCaches();setRefreshKey(x=>x+1)};
  const openAnalysis=async(id:string)=>{setError("");try{const r=await loadAnalysis(id);setAnalysis(r);setPage("New Analysis")}catch(e){setError(String(e))}};
  return <div className="app-shell"><aside className="sidebar">
    <div className="brand"><div className="brand-mark brand-image"><img src={mailScopeIcon} alt="MailScope"/></div><div><strong>MailScope</strong><span>EMAIL INTELLIGENCE</span></div></div>
    <nav>{navItems.map(([pageKey,label,Icon])=><button key={pageKey} className={page===pageKey?"nav-active":""} onClick={()=>{setError("");setPage(pageKey)}}><Icon size={18}/><span>{label}</span></button>)}</nav>
  </aside><main className="main">
    <header className="topbar"><div><h1>{pageTitles[page]}</h1><p>{page==="New Analysis"?(analysis?"Active local investigation":"Analyze an email without uploading its content"):pageDescriptions[page]}</p></div></header>
    {error&&<div className="error-banner"><AlertTriangle size={18}/><span>{error}</span></div>}
    {page==="New Analysis"&&analysis?.duplicate&&<div className="info-box duplicate-notice"><ShieldCheck size={18}/><span><strong>Email already analyzed.</strong> {analysis.duplicate_message||"The existing saved result was opened; no duplicate was created."}</span></div>}
    {page==="Dashboard"&&<Dashboard refreshKey={refreshKey} openAnalysis={openAnalysis} setError={setError}/>}
    {page==="New Analysis"&&<NewAnalysis engine={engine} engineChecking={engineChecking} retryEngine={checkEngine} analysis={analysis} setAnalysis={setAnalysis} selectedPath={selectedPath} setSelectedPath={setSelectedPath} loading={loading} setLoading={setLoading} setError={setError} onSaved={dataChanged}/>}
    {page==="History"&&<HistoryPage refreshKey={refreshKey} openAnalysis={openAnalysis} changed={dataChanged} setError={setError}/>}
    {page==="IOC Explorer"&&<IocExplorer refreshKey={refreshKey} setError={setError}/>}
    {page==="Threat Intelligence"&&<ThreatIntelligence setError={setError}/>}
    {page==="Reports"&&<Reports refreshKey={refreshKey} setError={setError}/>}
    {page==="Settings"&&<SettingsPage setError={setError}/>}
  </main></div>
}
const pageDescriptions:Record<Page,string>={Dashboard:"Local analysis activity and recent cases", "New Analysis":"", History:"Review and manage saved analyses", "IOC Explorer":"Search indicators found across saved emails", "Threat Intelligence":"Configure privacy-safe online reputation providers", Reports:"Export analysis evidence for review", Settings:"Configure local application preferences"};

function NewAnalysis({engine,engineChecking,retryEngine,analysis,setAnalysis,selectedPath,setSelectedPath,loading,setLoading,setError,onSaved}:{engine:EngineStatus|null;engineChecking:boolean;retryEngine:()=>Promise<void>;analysis:AnalysisResult|null;setAnalysis:(x:AnalysisResult|null)=>void;selectedPath:string;setSelectedPath:(x:string)=>void;loading:boolean;setLoading:(x:boolean)=>void;setError:(x:string)=>void;onSaved:()=>void}){
 const [tab,setTab]=useState("Triage");
 const [evidenceFilter,setEvidenceFilter]=useState("Findings");
 const [dragging,setDragging]=useState(false);
 const [refreshingIntel,setRefreshingIntel]=useState(false);
 const counts=useMemo(()=>{const r={url:0,domain:0,ip:0,email:0};analysis?.iocs.forEach(i=>{if(i.type==="url")r.url++;else if(i.type==="domain")r.domain++;else if(i.type.includes("ip"))r.ip++;else if(i.type==="email")r.email++});return r},[analysis]);
 const acceptPath=(path:string)=>{if(!path.toLowerCase().endsWith(".eml")){setError("Only .eml email files are supported.");return}setError("");setSelectedPath(path);setAnalysis(null)};
 useEffect(()=>{let unlisten:(()=>void)|undefined;getCurrentWebview().onDragDropEvent(event=>{const payload=event.payload;if(payload.type==="enter"||payload.type==="over"){setDragging(true);return}if(payload.type==="leave"){setDragging(false);return}setDragging(false);const path=payload.paths.find(x=>x.toLowerCase().endsWith(".eml"));if(path)acceptPath(path);else setError("Drop a single .eml email file.")}).then(fn=>{unlisten=fn}).catch(()=>{});return()=>{unlisten?.()}},[]);
 const choose=async()=>{try{const p=await open({multiple:false,directory:false,filters:[{name:"Email message",extensions:["eml"]}]});if(typeof p==="string")acceptPath(p)}catch(e){setError(String(e))}};
 const run=async()=>{if(!engine||!selectedPath)return;setLoading(true);setError("");try{const r=await invoke<AnalysisResult>("analyze_email",{filePath:selectedPath});setAnalysis(r);setTab("Triage");setEvidenceFilter("Findings");if(!r.duplicate)onSaved()}catch(e){setError(String(e))}finally{setLoading(false)}};
 const refreshIntel=async()=>{if(!analysis||refreshingIntel)return;setRefreshingIntel(true);setError("");try{const refreshed=await invoke<AnalysisResult>("refresh_intelligence",{analysisId:analysis.analysis_id});setAnalysis(refreshed);onSaved()}catch(e){setError(String(e))}finally{setRefreshingIntel(false)}};
 const saveCase=async(changes:Record<string,unknown>)=>{if(!analysis)return;setError("");try{const saved=await invoke<CaseMetadata>("save_case",{analysisId:analysis.analysis_id,changes});const updated={...analysis,case:saved};setAnalysis(updated);cacheAnalysis(updated);onSaved()}catch(e){setError(String(e));throw e}};
 const failedSocTools=engine?.socTools?Object.entries(engine.socTools).filter(([,tool])=>!tool.available||tool.integrity!=="verified").map(([name])=>name):[];
 if(!analysis)return <section className="new-analysis">{!engine&&<div className="engine-retry"><AlertTriangle size={18}/><div><strong>{engineChecking?"Checking analysis engine…":"Analysis engine is unavailable"}</strong><span>{engineChecking?"Please wait while MailScope checks the local engine.":"Retry the local engine check without restarting MailScope."}</span></div><button className="secondary" disabled={engineChecking} onClick={()=>void retryEngine()}><RefreshCw size={15}/>{engineChecking?"Checking…":"Retry engine"}</button></div>}{failedSocTools.length>0&&<div className="engine-retry"><AlertTriangle size={18}/><div><strong>Bundled SOC tool integrity check failed</strong><span>{failedSocTools.join(", ")} will not be executed. Local MIME analysis remains available.</span></div><button className="secondary" onClick={()=>void retryEngine()}><RefreshCw size={15}/>Recheck tools</button></div>}<div className={`drop-zone ${dragging?"drag-active":""}`} role="button" tabIndex={0} onClick={()=>void choose()} onKeyDown={e=>{if(e.target===e.currentTarget&&(e.key==="Enter"||e.key===" ")){e.preventDefault();void choose()}}}><div className="drop-icon"><Mail size={34}/></div><h2>{dragging?"Drop the .eml file here":"Select or drop an email file"}</h2><p>Choose a local RFC 822 message. The original email remains on this device.</p><button type="button" className="secondary" onClick={e=>{e.stopPropagation();void choose()}}>Select .eml file</button>{selectedPath&&<div className="selected-file">{selectedPath}</div>}</div><div className="option-grid"><div><ShieldCheck/><strong>Local parsing</strong><span>Headers and MIME parts are processed offline.</span></div><div><Search/><strong>IOC extraction</strong><span>URLs, domains, IPs and email addresses.</span></div><div><Paperclip/><strong>Bundled attachment analysis</strong><span>Verified capa, FLOSS and ExifTool binaries.</span></div></div><button className="primary" disabled={!selectedPath||!engine||loading} onClick={run}>{loading?"Analyzing…":"Start Analysis"}</button></section>;
 const tabs=["Triage","Evidence","Message","Report"];
 return <section className="investigation-shell"><div className="investigation-command"><div><span>ACTIVE INVESTIGATION</span><strong>{analysis.source.file_name}</strong><small>{analysis.email.subject||"No subject"} · {dateFmt(analysis.created_at)}</small></div><div className={`command-risk risk-text-${analysis.risk?.level||"informational"}`}><span>RISK</span><strong>{(analysis.risk?.level||"informational").toUpperCase()} <b>{analysis.risk?.score||0}</b></strong></div></div><div className="summary-row"><Card label="URLs" value={counts.url}/><Card label="Domains" value={counts.domain}/><Card label="IP addresses" value={counts.ip}/><Card label="Findings" value={analysis.findings?.length||0}/><Card label="Attachments" value={analysis.attachments.length}/></div><div className="workflow-tabs">{tabs.map((t,index)=><button key={t} className={tab===t?"workflow-active":""} onClick={()=>setTab(t)}><span>0{index+1}</span>{t}</button>)}</div><div className="investigation-stage">{tab==="Triage"&&<TriageView a={analysis} setError={setError} refreshIntel={refreshIntel} refreshingIntel={refreshingIntel} saveCase={saveCase}/>} {tab==="Evidence"&&<EvidenceView a={analysis} filter={evidenceFilter} setFilter={setEvidenceFilter} setError={setError}/>} {tab==="Message"&&<MessageView a={analysis} setError={setError}/>} {tab==="Report"&&<InlineReport a={analysis} setError={setError}/>}</div><button className="secondary back-button" onClick={()=>{setAnalysis(null);setSelectedPath("")}}>New investigation</button></section>
}

function TriageView({a,setError,refreshIntel,refreshingIntel,saveCase}:{a:AnalysisResult;setError:(x:string)=>void;refreshIntel:()=>Promise<void>;refreshingIntel:boolean;saveCase:(changes:Record<string,unknown>)=>Promise<void>}){const important=[...(a.findings||[])].sort((left,right)=>((right.risk_points??severityRank[right.severity]??0)-(left.risk_points??severityRank[left.severity]??0))).slice(0,3);return <div className="triage-layout"><section className={`triage-verdict risk-${a.risk?.level||"informational"}`}><span>TRIAGE VERDICT</span><div className="verdict-score"><strong>{a.risk?.score||0}</strong><small>/100</small></div><h2>{(a.risk?.level||"informational").toUpperCase()}</h2><p>{important[0]?.title||a.risk?.reasons?.[0]||"No elevated risk reason was produced."}</p><div className="verdict-meta"><small>Analysis coverage: {(a.risk?.coverage||a.risk?.confidence||"unknown").toUpperCase()}</small><small>Risk model: {a.risk?.model_version||"legacy"}</small><small>{a.intelligence?.refreshed_at?`Intel refreshed ${dateFmt(a.intelligence.refreshed_at)}`:"Intelligence has not been refreshed"}</small></div><button className="secondary refresh-intel" disabled={refreshingIntel} onClick={()=>void refreshIntel()}><RefreshCw size={14}/>{refreshingIntel?"Refreshing…":"Refresh intelligence"}</button></section><section className="triage-priority"><div className="stage-heading"><span>PRIORITY FINDINGS</span><small>{a.findings?.length||0} total</small></div>{important.length?important.map(f=><article key={f.finding_id}><span className={`severity-dot severity-${f.severity}`}></span><div><strong>{f.title}</strong><p>{f.description}</p><small>{f.tool_id}{typeof f.risk_points==="number"?` · +${f.risk_points} points`:""}</small></div></article>):<div className="empty-state compact">No heuristic findings.</div>}</section><section className="triage-identity"><div className="stage-heading"><span>MESSAGE IDENTITY</span><small>static evidence</small></div><Overview a={a} setError={setError}/></section><CaseWorkflow a={a} saveCase={saveCase}/></div>}

function CaseWorkflow({a,saveCase}:{a:AnalysisResult;saveCase:(changes:Record<string,unknown>)=>Promise<void>}){const current=a.case;const [state,setState]=useState(current?.state||"New");const [analyst,setAnalyst]=useState(current?.assigned_analyst||"");const [decision,setDecision]=useState(current?.analyst_decision||"");const [closure,setClosure]=useState(current?.closure_reason||"");const [tags,setTags]=useState((current?.tags||[]).join(", "));const [note,setNote]=useState("");const [saving,setSaving]=useState(false);const [message,setMessage]=useState("");useEffect(()=>{setState(a.case?.state||"New");setAnalyst(a.case?.assigned_analyst||"");setDecision(a.case?.analyst_decision||"");setClosure(a.case?.closure_reason||"");setTags((a.case?.tags||[]).join(", "))},[a.analysis_id,a.case?.updated_at]);const submit=async()=>{setSaving(true);setMessage("");try{await saveCase({state,assigned_analyst:analyst,analyst_decision:decision,closure_reason:closure,tags:tags.split(",").map(x=>x.trim()).filter(Boolean),note});setNote("");setMessage("Case workflow saved.")}finally{setSaving(false)}};return <section className="case-workflow"><div className="stage-heading"><span>CASE WORKFLOW</span><small>{current?.events?.length||0} events</small></div><div className="case-form-grid"><label>State<select value={state} onChange={e=>setState(e.target.value as CaseMetadata["state"])}>{["New","Investigating","Benign","Malicious","Closed"].map(x=><option key={x}>{x}</option>)}</select></label><label>Assigned analyst<input value={analyst} onChange={e=>setAnalyst(e.target.value)} maxLength={120}/></label><label>Tags<input value={tags} onChange={e=>setTags(e.target.value)} placeholder="phishing, finance, priority"/></label><label>Decision<input value={decision} onChange={e=>setDecision(e.target.value)} maxLength={1000}/></label><label className="case-wide">Closure reason<input value={closure} onChange={e=>setClosure(e.target.value)} maxLength={1000}/></label><label className="case-wide">Append analyst note<textarea value={note} onChange={e=>setNote(e.target.value)} maxLength={4000}/></label></div><button className="secondary" disabled={saving} onClick={()=>void submit()}>{saving?"Saving…":"Save case workflow"}</button>{message&&<p className="success-text">{message}</p>}{current?.events?.length?<details className="case-events"><summary>Event history</summary>{current.events.slice(0,20).map(event=><div key={event.event_id}><strong>{event.event_type.replaceAll("_"," ")}</strong><span>{dateFmt(event.created_at)}</span><code>{JSON.stringify(event.details)}</code></div>)}</details>:null}</section>}

function EvidenceView({a,filter,setFilter,setError}:{a:AnalysisResult;filter:string;setFilter:(x:string)=>void;setError:(x:string)=>void}){const filters=[{name:"Findings",count:a.findings?.length||0},{name:"Indicators",count:a.iocs.length},{name:"Files",count:a.attachments.length},{name:"Tools",count:a.tool_reports?.length||0}];return <div className="evidence-workspace"><aside className="evidence-rail"><div><span>EVIDENCE INDEX</span><small>Select a category</small></div>{filters.map(x=><button key={x.name} className={filter===x.name?"evidence-active":""} onClick={()=>setFilter(x.name)}><span>{x.name}</span><b>{x.count}</b></button>)}</aside><section className="evidence-detail"><div className="stage-heading"><span>{filter.toUpperCase()}</span><small>selected evidence view</small></div>{filter==="Findings"&&<Findings a={a}/>} {filter==="Indicators"&&<IocTable iocs={a.iocs} setError={setError}/>} {filter==="Files"&&<Attachments a={a} setError={setError}/>} {filter==="Tools"&&<ToolReports a={a}/>}</section></div>}

function MessageView({a,setError}:{a:AnalysisResult;setError:(x:string)=>void}){const [view,setView]=useState("Preview");const views=["Preview","Headers","Source"];return <div className="message-workspace"><aside className="evidence-rail"><div><span>MESSAGE LAYERS</span><small>Safe local inspection</small></div>{views.map(x=><button key={x} className={view===x?"evidence-active":""} onClick={()=>setView(x)}><span>{x}</span></button>)}</aside><section className="evidence-detail"><div className="message-envelope"><div><span>FROM</span><strong>{a.email.from.address||"—"}</strong></div><div><span>SUBJECT</span><strong>{a.email.subject||"—"}</strong></div><div><span>DATE</span><strong>{a.email.date||"—"}</strong></div></div>{view==="Preview"&&<TextBlock value={a.email.content.text_preview||"No plain-text message body is available."} setError={setError}/>} {view==="Headers"&&<TextBlock value={a.email.raw_headers} setError={setError}/>} {view==="Source"&&<TextBlock value={a.email.raw_source_preview||"Raw RFC822 source is unavailable for analyses created before MailScope 1.0.20. Analyze the EML again to populate it."} setError={setError}/>}</section></div>}

function InlineReport({a,setError}:{a:AnalysisResult;setError:(x:string)=>void}){const [message,setMessage]=useState("");const exportOne=async(format:string)=>{setError("");setMessage("");try{const path=await save({filters:[{name:`${format.toUpperCase()} report`,extensions:[format]}],defaultPath:`MailScope-${reportStem(a.source.file_name)}.${format}`});if(!path)return;await invoke("export_analysis",{analysisId:a.analysis_id,outputPath:path,reportFormat:format});setMessage(`Saved: ${path}`)}catch(e){setError(String(e))}};return <div className="report-stage"><div><span>CASE HANDOFF</span><h2>Package this investigation</h2><p>Export the current findings without leaving the active case.</p></div><div className="report-options"><button onClick={()=>void exportOne("html")}><Download size={20}/><strong>HTML</strong><span>Readable analyst report</span></button><button onClick={()=>void exportOne("json")}><Download size={20}/><strong>JSON</strong><span>Complete evidence data</span></button><button onClick={()=>void exportOne("csv")}><Download size={20}/><strong>CSV</strong><span>Indicator handoff</span></button></div>{message&&<p className="success-text">{message}</p>}</div>}
function Dashboard({refreshKey,openAnalysis,setError}:{refreshKey:number;openAnalysis:(id:string)=>void;setError:(x:string)=>void}){const [s,setS]=useState<DashboardStats|null>(dashboardCache);const [loaded,setLoaded]=useState(Boolean(dashboardCache));useEffect(()=>{if(!dashboardCache)setLoaded(false);loadDashboard().then(setS).catch(e=>{setS(null);setError(String(e))}).finally(()=>setLoaded(true))},[refreshKey]);if(!loaded)return <div className="empty-state">Loading dashboard…</div>;if(!s)return <div className="empty-state">Dashboard data could not be loaded. Use another page and return to retry.</div>;return <><div className="summary-row"><Card label="Analyses" value={s.analysis_count}/><Card label="Unique IOCs" value={s.unique_ioc_count}/><Card label="Attachments" value={s.attachment_count}/><Card label="With errors" value={s.flagged_count}/></div><section className="section-card"><h2><BarChart3 size={18}/> Recent analyses</h2>{s.recent.length?<HistoryTable items={s.recent} openAnalysis={openAnalysis}/>:<div className="empty-state compact">No saved analyses yet.</div>}</section></>}
function HistoryPage({refreshKey,openAnalysis,changed,setError}:{refreshKey:number;openAnalysis:(id:string)=>void;changed:()=>void;setError:(x:string)=>void}){const [items,setItems]=useState<HistoryItem[]>(historyCache||[]);const [q,setQ]=useState("");const load=async(force=false)=>{setError("");try{setItems(await loadHistory(force))}catch(e){setError(String(e))}};useEffect(()=>{void load()},[refreshKey]);const filtered=items.filter(x=>`${x.file_name} ${x.subject} ${x.from_address} ${x.sha256}`.toLowerCase().includes(q.toLowerCase()));const del=async(id:string)=>{if(!confirm("Delete this saved analysis?"))return;setError("");try{await invoke("delete_analysis",{analysisId:id});analysisCache.delete(id);changed();await load(true)}catch(e){setError(String(e))}};return <section className="section-card"><div className="toolbar"><div className="searchbox"><Search size={16}/><input placeholder="Search history" value={q} onChange={e=>setQ(e.target.value)}/></div><button className="secondary" onClick={()=>void load(true)}><RefreshCw size={15}/> Refresh</button></div><HistoryTable items={filtered} openAnalysis={openAnalysis} deleteItem={del}/></section>}
function HistoryTable({items,openAnalysis,deleteItem}:{items:HistoryItem[];openAnalysis:(id:string)=>void;deleteItem?:(id:string)=>void}){return <div className="history-table"><div className="history-head"><span>Date</span><span>Email</span><span>State</span><span>Tags</span><span>From</span><span>IOCs</span><span></span></div>{items.map(x=><div className="history-row" key={x.analysis_id}><span>{dateFmt(x.created_at)}</span><button className="link-button" onClick={()=>openAnalysis(x.analysis_id)}><strong>{x.subject||x.file_name}</strong><small>{x.file_name}</small></button><span className={`case-state state-${(x.case_state||"New").toLowerCase()}`}>{x.case_state||"New"}</span><span className="history-tags">{(x.tags||[]).slice(0,3).join(", ")||"—"}</span><code>{x.from_address||"—"}</code><span>{x.ioc_count}</span><span>{deleteItem&&<button className="icon-danger" title="Delete" onClick={()=>deleteItem(x.analysis_id)}><Trash2 size={16}/></button>}</span></div>)}</div>}
function IocExplorer({refreshKey,setError}:{refreshKey:number;setError:(x:string)=>void}){
 const [items,setItems]=useState<HistoryItem[]>([]);const [selected,setSelected]=useState("");const [analysis,setAnalysis]=useState<AnalysisResult|null>(null);const [q,setQ]=useState("");const [type,setType]=useState("all");const [unique,setUnique]=useState(true);const [loadingCase,setLoadingCase]=useState(false);const [caseError,setCaseError]=useState("");
 useEffect(()=>{let active=true;loadHistory().then(x=>{if(!active)return;setItems(x);setSelected(current=>current&&x.some(i=>i.analysis_id===current)?current:(x[0]?.analysis_id||""))}).catch(e=>{if(active)setCaseError(String(e))});return()=>{active=false}},[refreshKey]);
 useEffect(()=>{let active=true;if(!selected){setAnalysis(null);return()=>{active=false}};const cached=analysisCache.get(selected);if(cached)setAnalysis(cached);else setLoadingCase(true);setCaseError("");loadAnalysis(selected).then(x=>{if(active)setAnalysis(x)}).catch(e=>{if(active){setAnalysis(null);setCaseError(`Case could not be opened: ${String(e)}`)}}).finally(()=>{if(active)setLoadingCase(false)});return()=>{active=false}},[selected,refreshKey]);
 const valid=(i:IOC|undefined|null)=>{if(!i||typeof i.normalized_value!=="string"||typeof i.type!=="string")return false;const v=i.normalized_value.trim();if(!v||v.includes("=")||/\s/.test(v))return false;if(i.type==="domain")return v.includes(".")&&!v.startsWith(".")&&!v.endsWith(".");return true};
 const source=((analysis?.iocs||[]) as IOC[]).filter(valid);const types=["all","url","domain","ipv4","ipv6","email"];
 const rows=source.filter(i=>(type==="all"||i.type===type)&&i.normalized_value.toLowerCase().includes(q.toLowerCase())).filter((i,index,arr)=>!unique||arr.findIndex(x=>x.type===i.type&&x.normalized_value===i.normalized_value)===index);
 const counts={all:source.length,url:source.filter(x=>x.type==="url").length,domain:source.filter(x=>x.type==="domain").length,ipv4:source.filter(x=>x.type==="ipv4").length,ipv6:source.filter(x=>x.type==="ipv6").length,email:source.filter(x=>x.type==="email").length};
 const sender=analysis?.email?.from?.address||"Unknown sender";const subject=analysis?.email?.subject||analysis?.source?.file_name||"Untitled analysis";const riskScore=analysis?.risk?.score??0;const attachmentCount=analysis?.attachments?.length??0;
 return <div className="ioc-workspace"><aside className="analysis-picker"><div className="picker-title"><strong>Saved analyses</strong><span>{items.length} cases</span></div>{items.map(x=><button type="button" key={x.analysis_id} className={selected===x.analysis_id?"case-active":""} onClick={()=>{setAnalysis(null);setSelected(x.analysis_id)}}><strong>{x.subject||x.file_name||"Untitled case"}</strong><span>{x.file_name||"Unknown file"}</span><small>{dateFmt(x.created_at)} · {x.ioc_count||0} IOCs</small></button>)}</aside><section className="section-card ioc-case-panel">{caseError?<div className="case-error"><AlertTriangle size={18}/><div><strong>Unable to open this case</strong><span>{caseError}</span></div></div>:loadingCase?<div className="empty-state">Loading selected case…</div>:analysis?<><div className="case-summary"><div><span>Selected analysis</span><strong>{subject}</strong><small>{sender}</small></div><Card label="Risk" value={riskScore}/><Card label="Indicators" value={source.length}/><Card label="Attachments" value={attachmentCount}/></div><div className="ioc-tabs">{types.map(t=><button type="button" key={t} className={type===t?"tab-active":""} onClick={()=>setType(t)}>{t.toUpperCase()} <span>{counts[t as keyof typeof counts]||0}</span></button>)}</div><div className="toolbar"><div className="searchbox"><Search size={16}/><input placeholder="Search in selected analysis" value={q} onChange={e=>setQ(e.target.value)}/></div><label className="inline-check"><input type="checkbox" checked={unique} onChange={e=>setUnique(e.target.checked)}/> Hide duplicates</label></div><div className="ioc-explorer"><div className="ioc-head"><span>Type</span><span>Value</span><span>Scope</span><span>Source</span><span>Safe query</span><span></span></div>{rows.map((i,index)=><div className="ioc-row" key={`${i.type}:${i.normalized_value}:${index}`}><span className="type-badge">{i.type}</span><code>{i.normalized_value}</code><span>{i.classification?.scope||"unknown"}</span><span>{i.source?.location||"unknown"}</span><span>{i.classification?.is_safe_to_query?"Yes":"No"}</span><CopyButton value={i.normalized_value} setError={setError}/></div>)}{!rows.length&&<div className="empty-state compact">No indicators match this view.</div>}</div></>:<div className="empty-state">Select or create an analysis first.</div>}</section></div>}
function Reports({refreshKey,setError}:{refreshKey:number;setError:(x:string)=>void}){const [items,setItems]=useState<HistoryItem[]>(historyCache||[]);const [id,setId]=useState("");const [format,setFormat]=useState("html");const [message,setMessage]=useState("");useEffect(()=>{loadHistory().then(x=>{setItems(x);setId(current=>x.some(item=>item.analysis_id===current)?current:(x[0]?.analysis_id||""))}).catch(e=>{setItems([]);setId("");setError(String(e))})},[refreshKey]);const exportIt=async()=>{if(!id)return;setError("");setMessage("");try{const ext=format;const path=await save({filters:[{name:`${format.toUpperCase()} report`,extensions:[ext]}],defaultPath:`MailScope-report.${ext}`});if(!path)return;await invoke("export_analysis",{analysisId:id,outputPath:path,reportFormat:format});setMessage(`Report exported successfully: ${path}`)}catch(e){setError(String(e))}};return <section className="section-card report-form"><h2><Download size={18}/> Export report</h2><label>Saved analysis<select value={id} onChange={e=>setId(e.target.value)}>{items.map(x=><option key={x.analysis_id} value={x.analysis_id}>{x.subject||x.file_name} — {dateFmt(x.created_at)}</option>)}</select></label><label>Format<select value={format} onChange={e=>setFormat(e.target.value)}><option value="html">HTML report</option><option value="json">JSON evidence</option><option value="csv">CSV indicators</option></select></label><button className="primary inline" disabled={!id} onClick={()=>void exportIt()}>Export report</button>{message&&<p className="success-text">{message}</p>}</section>}
type OnlineSettings={online_intelligence:boolean;verify_email_authentication:boolean;query_hashes:boolean;query_urls:boolean;query_domains:boolean;query_ips:boolean;upload_attachments:boolean;upload_emails:boolean;abusech_auth_key:string;urlscan_api_key:string;virustotal_api_key:string;otx_api_key:string;abuseipdb_api_key:string;max_queries_per_provider:number;history_retention_days:number;trusted_authserv_ids:string[]};
const defaultOnline:OnlineSettings={online_intelligence:true,verify_email_authentication:true,query_hashes:true,query_urls:true,query_domains:true,query_ips:true,upload_attachments:false,upload_emails:false,abusech_auth_key:"",urlscan_api_key:"",virustotal_api_key:"",otx_api_key:"",abuseipdb_api_key:"",max_queries_per_provider:8,history_retention_days:30,trusted_authserv_ids:[]};
function useOnlineSettings(setError:(x:string)=>void){const [settings,setSettings]=useState<OnlineSettings>(settingsCache||defaultOnline);const [loaded,setLoaded]=useState(Boolean(settingsCache));useEffect(()=>{loadOnlineSettings().then(setSettings).catch(e=>setError(String(e))).finally(()=>setLoaded(true))},[]);const persist=async()=>{const saved=await invoke<OnlineSettings>("save_settings",{settings});settingsCache={...defaultOnline,...saved};setSettings(settingsCache);return settingsCache};return {settings,setSettings,loaded,persist}}
const providerLogos:Record<string,string>={URLhaus:urlhausLogo,ThreatFox:threatfoxLogo,MalwareBazaar:malwarebazaarLogo,"urlscan.io":urlscanLogo,"CIRCL Hashlookup":circlLogo,VirusTotal:vtLogo,"AlienVault OTX":otxLogo,AbuseIPDB:abuseipdbLogo};
function ProviderApiKeyFields({settings,update}:{settings:OnlineSettings;update:(change:Partial<OnlineSettings>)=>void}){return <><h2><Fingerprint size={18}/> Provider API keys</h2><div className="info-box provider-key-info"><ShieldCheck size={18}/><span><strong>One abuse.ch Auth-Key activates three providers:</strong> URLhaus, ThreatFox, and MalwareBazaar. urlscan.io, VirusTotal, AlienVault OTX, and AbuseIPDB each require their own key. CIRCL Hashlookup requires no key.</span></div><label>abuse.ch shared Auth-Key<span className="field-help">Enter the single Auth-Key from your abuse.ch account. It is reused only for URLhaus, ThreatFox, and MalwareBazaar requests.</span><input type="password" autoComplete="off" spellCheck={false} value={settings.abusech_auth_key} onChange={e=>update({abusech_auth_key:e.target.value})} placeholder="Required for URLhaus, ThreatFox, and MalwareBazaar"/></label><label>urlscan.io API key<span className="field-help">MailScope searches existing scans by domain. It never submits a URL for a new scan.</span><input type="password" autoComplete="off" spellCheck={false} value={settings.urlscan_api_key} onChange={e=>update({urlscan_api_key:e.target.value})} placeholder="Enter urlscan.io API key"/></label><label>VirusTotal API key<input type="password" autoComplete="off" spellCheck={false} value={settings.virustotal_api_key} onChange={e=>update({virustotal_api_key:e.target.value})} placeholder="Enter VirusTotal API key"/></label><label>AlienVault OTX API key<input type="password" autoComplete="off" spellCheck={false} value={settings.otx_api_key} onChange={e=>update({otx_api_key:e.target.value})} placeholder="Enter AlienVault OTX API key"/></label><label>AbuseIPDB API key<input type="password" autoComplete="off" spellCheck={false} value={settings.abuseipdb_api_key} onChange={e=>update({abuseipdb_api_key:e.target.value})} placeholder="Enter AbuseIPDB API key"/></label></>}
function ThreatIntelligence({setError}:{setError:(x:string)=>void}){const {settings,setSettings,loaded,persist}=useOnlineSettings(setError);const [message,setMessage]=useState("");if(!loaded)return <div className="empty-state">Loading provider settings…</div>;const update=(change:Partial<OnlineSettings>)=>{setMessage("");setSettings({...settings,...change})};const providers=[{name:"URLhaus",key:"Shared abuse.ch Auth-Key",configured:!!settings.abusech_auth_key,keyless:false,description:"Malicious URL reputation"},{name:"ThreatFox",key:"Shared abuse.ch Auth-Key",configured:!!settings.abusech_auth_key,keyless:false,description:"IOC and malware intelligence"},{name:"MalwareBazaar",key:"Shared abuse.ch Auth-Key",configured:!!settings.abusech_auth_key,keyless:false,description:"Attachment hash reputation"},{name:"urlscan.io",key:"Search API key · no submissions",configured:!!settings.urlscan_api_key,keyless:false,description:"Historical URL and domain scans"},{name:"CIRCL Hashlookup",key:"Public API · no key required",configured:true,keyless:true,description:"Known-file hash context"},{name:"VirusTotal",key:"API key",configured:!!settings.virustotal_api_key,keyless:false,description:"Multi-engine reputation"},{name:"AlienVault OTX",key:"API key",configured:!!settings.otx_api_key,keyless:false,description:"Pulse-based IOC intelligence"},{name:"AbuseIPDB",key:"API key",configured:!!settings.abuseipdb_api_key,keyless:false,description:"IP abuse reputation"}];const saveProviderSettings=async()=>{setError("");setMessage("");try{await persist();setMessage("Threat intelligence settings saved securely.")}catch(e){setError(String(e))}};return <section><div className="section-card settings-form"><h2><Globe2 size={18}/> Online intelligence</h2><label className="check"><input type="checkbox" checked={settings.online_intelligence} onChange={e=>update({online_intelligence:e.target.checked})}/><span>Use online providers when an internet connection is available</span></label><div className="info-box"><ShieldCheck size={18}/><span>These labels show configuration status, not live provider health. MailScope sends only privacy-safe indicators and hashes; complete emails and attachments are never uploaded.</span></div><div className="provider-grid">{providers.map(p=>{const logo=providerLogos[p.name];const disabled=!settings.online_intelligence;const status=disabled?"Disabled":p.keyless?"Ready":p.configured?"Key saved":"Key required";const tone=disabled?"disabled":p.keyless||p.configured?"ready":"key";return <article className={`provider-card provider-card-${tone}`} key={p.name}><div className={`provider-icon provider-brand-icon ${p.name==="ThreatFox"?"provider-threatfox":""}`}><img src={logo} alt={`${p.name} logo`}/></div><div className="provider-copy"><strong>{p.name}</strong><span>{p.description}</span><small>{p.key}</small></div><em className={`provider-${tone}`}>{status}</em></article>})}</div><ProviderApiKeyFields settings={settings} update={update}/><button className="primary inline" onClick={()=>void saveProviderSettings()}>Save provider settings</button>{message&&<p className="success-text">{message}</p>}</div></section>}
function SettingsPage({setError}:{setError:(x:string)=>void}){const {settings,setSettings,loaded,persist}=useOnlineSettings(setError);const [message,setMessage]=useState("");if(!loaded)return <div className="empty-state">Loading settings…</div>;const update=(change:Partial<OnlineSettings>)=>{setMessage("");setSettings({...settings,...change})};const saveAll=async()=>{setError("");setMessage("");try{await persist();setMessage("Settings saved locally. Retention cleanup is now active.")}catch(e){setError(String(e))}};return <><section className="section-card settings-form"><h2><Settings size={18}/> Application settings</h2><label>History retention<select value={settings.history_retention_days} onChange={e=>update({history_retention_days:Number(e.target.value)})}><option value={0}>Keep until manually deleted</option><option value={30}>30 days</option><option value={90}>90 days</option></select></label><h2><Globe2 size={18}/> Query policy</h2><div className="info-box"><ShieldCheck size={18}/><span>Online provider activation and API keys are managed only on the Threat Intelligence page.</span></div><label className={`check ${!settings.online_intelligence?"disabled":""}`}><input type="checkbox" checked={settings.verify_email_authentication} disabled={!settings.online_intelligence} onChange={e=>update({verify_email_authentication:e.target.checked})}/><span>Revalidate DKIM, SPF, and DMARC with DNS</span></label><label>Trusted Authentication-Results gateways<span className="field-help">Only exact authserv-id values from gateways you control are allowed to influence risk. Separate multiple values with commas.</span><input type="text" spellCheck={false} value={settings.trusted_authserv_ids.join(", ")} onChange={e=>update({trusted_authserv_ids:e.target.value.split(",").map(x=>x.trim().toLowerCase()).filter(Boolean).slice(0,20)})} placeholder="mailgateway.example.com, mx.example.com"/></label><div className="query-grid">{[["query_hashes","Hashes"],["query_urls","URLs"],["query_domains","Domains"],["query_ips","IP addresses"]].map(([k,l])=><label className="check" key={k}><input type="checkbox" checked={Boolean(settings[k as keyof OnlineSettings])} onChange={e=>update({[k]:e.target.checked})}/><span>Query {l}</span></label>)}</div><label>Maximum lookups per provider<input type="number" min="1" max="25" value={settings.max_queries_per_provider} onChange={e=>update({max_queries_per_provider:Math.max(1,Math.min(25,Number(e.target.value)||1))})}/></label><label className="check disabled"><input type="checkbox" checked={false} disabled/><span>Upload attachments automatically (disabled for privacy)</span></label><label className="check disabled"><input type="checkbox" checked={false} disabled/><span>Upload complete emails automatically (disabled for privacy)</span></label><div className="info-box"><ShieldCheck size={18}/><span>Authentication revalidation sends only DKIM selector/domain and SPF/DMARC DNS queries; complete emails and attachments are never uploaded.</span></div><button className="primary inline" onClick={()=>void saveAll()}>Save settings</button>{message&&<p className="success-text">{message}</p>}</section><SecurityOperations setError={setError}/></>}

function SecurityOperations({setError}:{setError:(x:string)=>void}){const [audit,setAudit]=useState<AuditEntry[]>([]);const [yara,setYara]=useState<YaraStatus|null>(null);const [message,setMessage]=useState("");const [busy,setBusy]=useState(false);const load=async()=>{try{const [auditRows,yaraState]=await Promise.all([invoke<AuditEntry[]>("list_audit",{limit:100}),invoke<YaraStatus>("get_yara_status")]);setAudit(auditRows);setYara(yaraState)}catch(e){setError(String(e))}};useEffect(()=>{void load()},[]);const task=async(action:()=>Promise<void>)=>{setBusy(true);setMessage("");setError("");try{await action()}catch(e){setError(String(e))}finally{setBusy(false)}};const create=()=>task(async()=>{const output=await save({defaultPath:"MailScope-backup.msbackup",filters:[{name:"MailScope backup",extensions:["msbackup"]}]});if(!output)return;await invoke("create_backup",{outputPath:output});setMessage(`Encrypted-settings backup created: ${output}`);await load()});const restore=()=>task(async()=>{const input=await open({multiple:false,directory:false,filters:[{name:"MailScope backup",extensions:["msbackup"]}]});if(typeof input!=="string")return;if(!window.confirm("Restore this backup? Current data will first be backed up automatically, then replaced."))return;await invoke("restore_backup",{inputPath:input});historyCache=null;dashboardCache=null;settingsCache=null;analysisCache.clear();bootstrapRequest=null;setMessage("Backup restored. Reloading the application…");window.setTimeout(()=>window.location.reload(),500)});const importRule=()=>task(async()=>{const input=await open({multiple:false,directory:false,filters:[{name:"YARA rule",extensions:["yar","yara"]}]});if(typeof input!=="string")return;await invoke("import_yara_rule",{path:input});setMessage("YARA rule compiled, versioned, and activated.");await load()});const toggleRule=(name:string,digest:string)=>task(async()=>{await invoke("set_yara_rule_active",{name,digest});setMessage(digest?"YARA rule version activated.":"YARA rule disabled.");await load()});return <section className="security-operations"><div className="section-card"><h2><Database size={18}/> Backup and recovery</h2><p className="operation-copy">Create a validated <code>.msbackup</code> archive containing the case database, encrypted settings, and local evidence workspace. Restore always creates an automatic rollback backup first.</p><div className="operation-actions"><button className="secondary" disabled={busy} onClick={()=>void create()}><Download size={15}/>Create backup</button><button className="secondary" disabled={busy} onClick={()=>void restore()}><RotateCcw size={15}/>Restore backup</button></div></div><div className="section-card"><h2><Bug size={18}/> Managed YARA rules</h2><p className="operation-copy">Bundled pack: <strong>{yara?.bundled?.ruleset_version||"loading"}</strong> · {yara?.bundled?.rule_files||0} files · integrity {yara?.bundled?.integrity||"unknown"}. Imported rules must compile successfully and run only inside the isolated worker.</p><button className="secondary" disabled={busy} onClick={()=>void importRule()}><FilePlus2 size={15}/>Import rule</button><div className="yara-list">{yara?.custom_rules?.map(rule=><article key={rule.name}><div className="yara-rule-info"><strong>{rule.name}</strong><small>{rule.versions.length} version(s) · {rule.enabled?"active":"disabled"}</small><div className="yara-versions">{rule.versions.map(version=><button key={version.sha256} className={rule.active===version.sha256?"version-active":""} disabled={busy||rule.active===version.sha256} title={version.sha256} onClick={()=>void toggleRule(rule.name,version.sha256)}>{version.sha256.slice(0,8)}{rule.active===version.sha256?" active":" activate"}</button>)}</div></div><button className="secondary compact-button" disabled={busy||!rule.enabled} onClick={()=>void toggleRule(rule.name,"")}>Disable</button></article>)}{!yara?.custom_rules?.length&&<div className="empty-state compact">No custom rules imported.</div>}</div></div><div className="section-card audit-panel"><h2><ShieldCheck size={18}/> Privacy audit log</h2><p className="operation-copy">Provider activity stores only an indicator digest, provider outcome, cache status, and privacy controls—not the original query value.</p><button className="secondary" disabled={busy} onClick={()=>void load()}><RefreshCw size={15}/>Refresh log</button><div className="audit-list">{audit.slice(0,50).map(row=><article key={row.event_id}><span>{dateFmt(row.created_at)}</span><strong>{row.event_type.replaceAll("_"," ")}</strong><code>{row.provider_id||"local"} · {row.indicator_type||"—"} · {row.outcome||"—"}</code><small>{row.indicator_digest?`${row.indicator_digest.slice(0,16)}…`:"no indicator value stored"}</small></article>)}{!audit.length&&<div className="empty-state compact">No audit events yet.</div>}</div></div>{message&&<p className="success-text operations-message">{message}</p>}</section>}
function Card({label,value}:{label:string;value:number}){return <div className="summary-card"><span>{label}</span><strong>{value}</strong></div>}
async function copyValue(value:string,setError:(x:string)=>void){try{await navigator.clipboard.writeText(value);setError("")}catch(e){setError(`Could not copy to clipboard: ${String(e)}`)}}
function CopyButton({value,setError}:{value:string;setError:(x:string)=>void}){return <button type="button" className="copy-button" title="Copy" aria-label="Copy value" onClick={()=>void copyValue(value,setError)}><Copy size={14}/></button>}
function TextBlock({value,setError}:{value:string;setError:(x:string)=>void}){return <div className="text-block"><div className="text-block-actions"><CopyButton value={value} setError={setError}/></div><pre>{value}</pre></div>}
function Overview({a,setError}:{a:AnalysisResult;setError:(x:string)=>void}){const rows=[["Subject",a.email.subject||"—"],["From",a.email.from.address||"—"],["Reply-To",a.email.reply_to.map(x=>x.address).join(", ")||"—"],["Return-Path",a.email.return_path||"—"],["Date",a.email.date||"—"],["Message-ID",a.email.message_id||"—"],["File size",fmt(a.source.file_size)],["SHA-256",a.source.sha256]];return <div>{rows.map(([l,v])=><div className="detail-row" key={l}><span>{l}</span><code>{v}</code><CopyButton value={v} setError={setError}/></div>)}</div>}
function IocTable({iocs,setError}:{iocs:IOC[];setError:(x:string)=>void}){return <div className="table"><div className="table-head"><span>Type</span><span>Value</span><span>Scope</span><span>Source</span><span></span></div>{iocs.map(i=><div className="table-row" key={i.ioc_id}><span className="type-badge">{i.type}</span><code>{i.normalized_value}</code><span>{i.classification.scope}</span><span>{i.source.location}</span><CopyButton value={i.normalized_value} setError={setError}/></div>)}</div>}
function Attachments({a,setError}:{a:AnalysisResult;setError:(x:string)=>void}){if(!a.attachments.length)return <div className="empty-state">No attachments were found.</div>;return <div className="attachment-list">{a.attachments.map(x=><article className={x.is_embedded?"attachment-embedded":""} style={{marginLeft:`${Math.min(x.depth||0,3)*22}px`}} key={x.attachment_id}><div className="attachment-title"><Paperclip size={18}/><div><strong>{x.is_embedded?"↳ ":""}{x.file_name}</strong><span>{x.declared_content_type} · detected: {x.detected_type||"unknown"} · {fmt(x.size)} · entropy {x.entropy??0}</span><div className="attachment-meta"><em className={`analysis-status status-${x.analysis_status||"analyzed"}`}>{(x.analysis_status||"analyzed").replaceAll("_"," ")}</em>{x.extracted_from&&<small>extracted from {x.extracted_from}</small>}</div></div></div>{x.extraction_notes?.map(note=><div className="attachment-note" key={note}>{note}</div>)}{x.static_flags?.map(f=><div className="attachment-flag" key={f}><AlertTriangle size={14}/>{f}</div>)}{Object.entries(x.hashes).map(([k,v])=><div className="hash-row" key={k}><span>{k.toUpperCase()}</span><code>{v}</code><CopyButton value={v} setError={setError}/></div>)}</article>)}</div>}

const toolIcons:Record<string,any>={auth_headers:Shield,identity_guard:Fingerprint,html_inspector:Code2,ioc_extractor:Link2,content_linguistics:Languages,received_chain:Route,attachment_static:FileWarning,threat_intel:Globe2,online_status:Globe2,yara:Bug,pdf_analyzer:FileSearch,office_analyzer:FileWarning,pe_analyzer:Server,capa:Radar,floss:Eye,exiftool:Archive};
// Only providers that publish an official icon are represented by a brand asset.
// Local analyzers without an official project mark use neutral Lucide symbols.
const toolLogos:Record<string,string>={urlhaus:urlhausLogo,threatfox:threatfoxLogo,malwarebazaar:malwarebazaarLogo,urlscan:urlscanLogo,circl_hashlookup:circlLogo,virustotal:vtLogo,otx:otxLogo,abuseipdb:abuseipdbLogo};
function Findings({a}:{a:AnalysisResult}){if(!a.findings?.length)return <div className="empty-state">No heuristic findings were produced.</div>;return <div className="finding-list">{a.findings.map(f=><article className={`finding-card severity-${f.severity}`} key={f.finding_id}><div><span className="severity-badge">{f.severity}</span><strong>{f.title}</strong></div><p>{f.description}</p>{f.evidence&&<code>{f.evidence}</code>}<small>Source: {f.tool_id}</small></article>)}</div>}
function ToolReports({a}:{a:AnalysisResult}){return <div><div className={`risk-banner risk-${a.risk?.level||"informational"}`}><Shield size={26}/><div><strong>Risk {a.risk?.score||0}/100 · {(a.risk?.level||"informational").toUpperCase()}</strong><span>{a.risk?.reasons?.slice(0,3).join(" · ")||"No elevated risk reasons"}</span></div></div><div className="tool-grid">{(a.tool_reports||[]).map(t=>{const Icon=toolIcons[t.tool_id]||Database;const logo=toolLogos[t.tool_id];return <article className="tool-card" key={t.tool_id}><div className="tool-card-head"><div className={`tool-icon ${logo?`tool-brand-icon ${t.tool_id==="threatfox"?"provider-threatfox":""}`:""}`}>{logo?<img src={logo} alt={`${t.name} logo`}/>:<Icon size={22}/>}</div><div><strong>{t.name}</strong><span>{t.category}</span></div><em className={`tool-status status-${t.status}`}>{t.status}</em></div><p>{t.summary}</p>{Object.keys(t.metrics||{}).length>0&&<div className="tool-metrics">{Object.entries(t.metrics).map(([k,v])=><div key={k}><span>{k.replaceAll("_"," ")}</span><code>{String(v)}</code></div>)}</div>}{t.details?.map(d=><small key={d}>{d}</small>)}</article>})}</div></div>}
